package com.yuri.music;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;
// Official web content receives all keyboard/touch events directly. No JS credential hooks.
public final class YouTubeLoginActivity extends Activity{
 WebView web;TextView status;
 @Override public void onCreate(Bundle state){super.onCreate(state);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xff121016);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()),ime=insets.getInsets(WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);
 LinearLayout bar=new LinearLayout(this);Button back=new Button(this);back.setText("Cancelar");back.setOnClickListener(v->finish());Button browser=new Button(this);browser.setText("Navegador");browser.setOnClickListener(v->{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://music.youtube.com")));status.setText("Se o Google bloquear o login interno, use Importar sessão nas configurações. O app não pode ler a sessão do navegador externo.");});Button done=new Button(this);done.setText("Concluir");done.setOnClickListener(v->{String cookie=CookieManager.getInstance().getCookie("https://music.youtube.com");if(cookie!=null&&cookie.contains("SAPISID=")){CookieManager.getInstance().flush();finish();}else status.setText("A sessão ainda não está pronta. Termine o login ou volte para cancelar.");});bar.addView(back);bar.addView(browser);bar.addView(done);root.addView(bar);status=new TextView(this);status.setTextColor(0xffeeeeee);status.setPadding(16,4,16,8);status.setText("Entre na página oficial do YouTube Music. O Google pode restringir login em WebViews.");root.addView(status);
 web=new WebView(this);web.setFocusable(true);web.setFocusableInTouchMode(true);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri u=request.getUrl();String host=u.getHost();return !"https".equals(u.getScheme())||host==null||!(host.equals("youtube.com")||host.endsWith(".youtube.com")||host.equals("google.com")||host.endsWith(".google.com"));}@Override public void onReceivedError(WebView view,WebResourceRequest req,WebResourceError e){if(req.isForMainFrame())status.setText("Não foi possível carregar. Confira a conexão, volte ou tente novamente.");}@Override public void onReceivedSslError(WebView view,android.webkit.SslErrorHandler handler,android.net.http.SslError error){handler.cancel();status.setText("Conexão segura recusada. Confira a data e a rede do aparelho.");}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));if(state==null)web.loadUrl("https://music.youtube.com/");else web.restoreState(state);web.requestFocus(View.FOCUS_DOWN);}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);web.saveState(state);}@Override public void onBackPressed(){if(web.canGoBack())web.goBack();else finish();}@Override protected void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}
